                const std::size_t active = (std::bit_width(different) + 7) / 8;
                if (active == 1) {
                    for (T value : values) {
                        const Unsigned encoded = key(value);
                        ++counts[0][(encoded >> 0) & Unsigned{255}];
                    }
                    return different;
                }
                if (active == 2) {
                    for (T value : values) {
                        const Unsigned encoded = key(value);
                        ++counts[0][(encoded >> 0) & Unsigned{255}];
                        ++counts[1][(encoded >> 8) & Unsigned{255}];
                    }
                    return different;
                }
                if (active == 3) {
                    for (T value : values) {
                        const Unsigned encoded = key(value);
                        ++counts[0][(encoded >> 0) & Unsigned{255}];
                        ++counts[1][(encoded >> 8) & Unsigned{255}];
                        ++counts[2][(encoded >> 16) & Unsigned{255}];
                    }
                    return different;
                }
                if (active == 4) {
                    for (T value : values) {
                        const Unsigned encoded = key(value);
                        ++counts[0][(encoded >> 0) & Unsigned{255}];
                        ++counts[1][(encoded >> 8) & Unsigned{255}];
                        ++counts[2][(encoded >> 16) & Unsigned{255}];
                        ++counts[3][(encoded >> 24) & Unsigned{255}];
