            else
#endif
            {
                T previous = values.front();
                ordered = reversed = true;
                for (T value : values) {
                    check<HasMaximum>(value, maximum);
                    ordered &= previous <= value;
                    reversed &= previous >= value;
                    previous = value;
                    different |= key(value) ^ first;
                }
