                    for (T value : values) {
                        const Unsigned encoded = key(value);
                        ++counts[0][encoded & Unsigned{255}];
                        if (active > 1) ++counts[1][(encoded >> 8) & Unsigned{255}];
                        if (active > 2) ++counts[2][(encoded >> 16) & Unsigned{255}];
                        if (active > 3) ++counts[3][(encoded >> 24) & Unsigned{255}];
